--

CREATE TABLE `heat` (
  `number` int(11) NOT NULL COMMENT '編號',
  `type_id` int(11) NOT NULL COMMENT '類別id',
  `food_name` varchar(10) COLLATE utf8_bin NOT NULL COMMENT '食物名稱',
