--
-- 資料表結構 `menu`
--

CREATE TABLE `menu` (
  `code` int(11) NOT NULL,
  `store_name` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商家名稱',
  `sell_date` date NOT NULL COMMENT '日期',
  `dishes` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菜色',
  `price` int(11) NOT NULL COMMENT '價格',
  `detail` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '菜色內容介紹'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

